    /** C# MemoryExtensions.IndexOf(ReadOnlySpan&lt;T&gt;, ReadOnlySpan&lt;T&gt;) — subsequence search or -1. */
    public static <T> int indexOf(ReadOnlySpan<T> span, ReadOnlySpan<T> value) {
        if (span == null || value == null || value.length() == 0) return -1;
        int lastStart = span.length() - value.length();
        for (int i = 0; i <= lastStart; i++) {
            boolean matched = true;
            for (int j = 0; j < value.length(); j++) {
                if (!java.util.Objects.equals(span.get(i + j), value.get(j))) {
                    matched = false;
                    break;
                }
            }
            if (matched) return i;
        }
        return -1;
    }

    /**
     * C# MemoryExtensions.ToLower(ReadOnlySpan&lt;char&gt;, Span&lt;char&gt;, CultureInfo):
     * lowercases each source char into the destination span and returns the number
     * of chars written.
     */
    public static int toLowerCase(ReadOnlySpan<Character> source, Span<Character> destination, CultureInfo culture) {
        int count = 0;
        TextInfo textInfo = culture != null ? culture.getTextInfo() : CultureInfo.getInvariantCulture().getTextInfo();
        for (int i = 0; i < source.length(); i++) {
            char c = source.get(i);
            char lowered = textInfo.toLowerCase(c);
            destination.set(count, lowered);
            count++;
        }
        return count;
    }

